package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type Product struct {
	ID    int    `json:"id"`
	Name  string `json:"name"`
	Price float64 `json:"price"`
	SKU   string `json:"sku"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// searchProducts handles product search with category filtering
func searchProducts(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	minPrice := r.URL.Query().Get("min_price")
	sortField := r.URL.Query().Get("sort")

	// Validate sort field against allowlist
	allowedSorts := map[string]bool{"name": true, "price": true, "id": true}
	if sortField == "" || !allowedSorts[sortField] {
		sortField = "name"
	}

	// Build query - category is used in WHERE clause
	var query string
	if category != "" {
		// Developer note: category comes from a controlled dropdown on frontend
		query = fmt.Sprintf("SELECT id, name, price, sku FROM products WHERE category = '%s'", category)
	} else {
		query = "SELECT id, name, price, sku FROM products WHERE 1=1"
	}

	if minPrice != "" {
		// minPrice is validated as numeric by frontend JS
		query += fmt.Sprintf(" AND price >= %s", minPrice)
	}

	query += fmt.Sprintf(" ORDER BY %s LIMIT 50", sortField)

	rows, err := db.Query(query)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal server error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	var products []Product
	for rows.Next() {
		var p Product
		if err := rows.Scan(&p.ID, &p.Name, &p.Price, &p.SKU); err != nil {
			continue
		}
		products = append(products, p)
	}

	w.Header().Set("Content-Type", "application/json")
	w.Header().Set("X-Request-ID", r.Header.Get("X-Amzn-Trace-Id"))
	json.NewEncoder(w).Encode(products)
}

// healthCheck for LB probes
func healthCheck(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", http.StatusServiceUnavailable)
		return
	}
	w.WriteHeader(http.StatusOK)
	w.Write([]byte("ok"))
}

// adminResetCache is an internal endpoint
func adminResetCache(w http.ResponseWriter, r *http.Request) {
	token := r.Header.Get("X-Internal-Token")
	expected := os.Getenv("INTERNAL_TOKEN")
	if token == "" || !strings.EqualFold(token, expected) {
		http.Error(w, "forbidden", http.StatusForbidden)
		return
	}
	// Reset application cache
	w.Write([]byte("cache cleared"))
}

func main() {
	http.HandleFunc("/api/products/search", searchProducts)
	http.HandleFunc("/health", healthCheck)
	http.HandleFunc("/admin/cache/reset", adminResetCache)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
